file.content:
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        counts[port][cls] += 1
        results.append({"t": t, "port": port, "class": cls})
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "good": counts[name]["good"],
                "runt": counts[name]["runt"],
                "giant": counts[name]["giant"],
                "alignment": counts[name]["alignment"],
                "bad_fcs": counts[name]["bad_fcs"],
            }
            for name in ports
        ],
    }


FRAME_DECODE_FRAME_KEYS = frozenset({"t", "port", "data"})
FRAME_DECODE_DATA_RE = re.compile(r"[0-9a-f]+")
FRAME_DECODE_MIN_BYTES = 18
FRAME_DECODE_MIN_TAGGED_BYTES = 22
FRAME_DECODE_TAG = b"\x81\x00"


def validate_frame_decode_frames(frames, ports):
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    port_set = set(ports)
    result = []
    prev_t = None
    for frame in frames:
        if (
            not isinstance(frame, dict)
            or frozenset(frame) != FRAME_DECODE_FRAME_KEYS
        ):
            raise InvalidInput("bad frame")
        t = frame["t"]
        port = frame["port"]
        data = frame["data"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        if (
            not isinstance(data, str)
            or len(data) % 2 != 0
            or FRAME_DECODE_DATA_RE.fullmatch(data) is None
        ):
            raise InvalidInput("bad data")
        raw = bytes.fromhex(data)
        if len(raw) < FRAME_DECODE_MIN_BYTES:
            raise InvalidInput("frame too short")
        if raw[12:14] == FRAME_DECODE_TAG:
            # 单层 802.1Q：总长须容纳标签，且标签后不得再为 8100（双标签）
            if len(raw) < FRAME_DECODE_MIN_TAGGED_BYTES:
                raise InvalidInput("tagged frame too short")
            if raw[16:18] == FRAME_DECODE_TAG:
                raise InvalidInput("double tag")
        result.append((t, port, raw))
    return result


def _format_mac(octets):
    return ":".join("%02x" % byte for byte in octets)


def frame_decode(frames, max_frame):
    results = []
    for t, port, raw in frames:
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            priority = tci >> 13
            dei = (tci >> 12) & 1
            vlan = tci & 0x0FFF
            ethertype_offset = 16
        else:
            priority = None
            dei = None
            vlan = None
            ethertype_offset = 12
        ethertype = (raw[ethertype_offset] << 8) | raw[ethertype_offset + 1]
        body = raw[:-4]
        payload = raw[ethertype_offset + 2 : -4].hex()
        fcs = raw[-4:].hex()
        if len(raw) < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif len(raw) > max_frame:
            cls = "giant"
        elif raw[-4:] != (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little"):
            cls = "bad_fcs"
        else:
            cls = "good"
        results.append(
            {
                "t": t,
                "port": port,
                "class": cls,
                "dst": dst,
                "src": src,
                "vlan": vlan,
                "priority": priority,
                "dei": dei,
                "ethertype": ethertype,
                "payload": payload,
                "fcs": fcs,
            }
        )
    return {"results": results}


FRAME_ENCODE_FRAME_KEYS = frozenset(
    {"t", "port", "dst", "src", "vlan", "priority", "dei", "ethertype", "payload"}
)
FRAME_ENCODE_DATA_RE = re.compile(r"[0-9a-f]*")
FRAME_ENCODE_MIN_BODY = 60
FRAME_ENCODE_TAG_ETHERTYPE = 0x8100


def validate_frame_encode_frames(frames, ports):
    # t/port 沿用 frame-decode；dst/src 的 MAC 准入沿用 forward-decode
    # （dst 非零可组播/广播，src 须非零单播）
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    port_set = set(ports)
    result = []
    prev_t = None
    for frame in frames:
        if (
            not isinstance(frame, dict)
            or frozenset(frame) != FRAME_ENCODE_FRAME_KEYS
        ):
            raise InvalidInput("bad frame")
        t = frame["t"]
        port = frame["port"]
        dst = frame["dst"]
        src = frame["src"]
        vlan = frame["vlan"]
        priority = frame["priority"]
        dei = frame["dei"]
        ethertype = frame["ethertype"]
        payload = frame["payload"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(port, str) or port not in port_set:
            raise InvalidInput("unknown port")
        if not valid_dst_mac(dst):
            raise InvalidInput("bad dst")
        if not valid_mac(src):
            raise InvalidInput("bad src")
        if vlan is not None and (not _is_int(vlan) or not 1 <= vlan <= 4094):
            raise InvalidInput("bad vlan")
        if not _is_int(priority) or not 0 <= priority <= 7:
            raise InvalidInput("bad priority")
        if not isinstance(dei, bool):
            raise InvalidInput("bad dei")
        if vlan is None and (priority != 0 or dei):
            # 无标签帧不带 PCP/DEI：priority=0 且 dei=false
            raise InvalidInput("priority/dei require tag")
        if (
            not _is_int(ethertype)
            or not 0 <= ethertype <= 0xFFFF
            or ethertype == FRAME_ENCODE_TAG_ETHERTYPE
        ):
            raise InvalidInput("bad ethertype")
        if payload is None:
            payload_bytes = b""
        elif (
            not isinstance(payload, str)
            or len(payload) % 2 != 0
            or FRAME_ENCODE_DATA_RE.fullmatch(payload) is None
        ):
            raise InvalidInput("bad payload")
        else:
            payload_bytes = bytes.fromhex(payload)
        result.append(
            (t, port, dst, src, vlan, priority, dei, ethertype, payload_bytes)
        )
    return result


def _mac_bytes(mac):
    return bytes(int(part, 16) for part in mac.split(":"))

# link-wire：在 link-forward 的协商/帧检查/VLAN/FDB 之上接入确定性线速模型。
# 配置沿用 link-forward，每口新增非负 queue_bytes；事件另接受 advance 项。
# 线上长度 = 标签增删后的帧长 + 8(前导码与定界符) + 12(帧间隔)；发送时长
# ceil(bytes*8000/rate) 纳秒。同一出口入队顺序串行；half 口自身发送区间收帧
# 即碰撞；离 up 先结算再以 link_down 丢弃未完成副本；队列按未完成副本线上
# 字节总和判满。advance 仅推进结算；末事件后不自动排空。
# ---------------------------------------------------------------------------

LINK_WIRE_CONFIG_KEYS = LINK_FORWARD_CONFIG_KEYS
LINK_WIRE_LINK_EVENT_KEYS = LINK_STATE_EVENT_KEYS
LINK_WIRE_FRAME_EVENT_KEYS = FORWARD_CHECK_FRAME_KEYS
LINK_WIRE_ADVANCE_EVENT_KEYS = frozenset(("t", "advance"))
LINK_WIRE_OVERHEAD = 8 + 12  # 前导码与定界符 8 字节 + 帧间隔 12 字节


def validate_link_wire_config(config):
    """link-wire 配置：同 link-forward，每口另需非负整数 queue_bytes。"""
    if (
        not isinstance(config, dict)
        or frozenset(config) != LINK_WIRE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    age = config["age"]
    if not _is_int(age) or age <= 0:
        raise InvalidInput("age must be a positive integer")
    port_docs = config["ports"]
    if not isinstance(port_docs, list) or not port_docs:
        raise InvalidInput("ports must be a non-empty list")
    expected = (PORT_KEYS_V2 - {"up"}) | {"rates", "modes", "queue_bytes"}
    names = []
    caps = {}
    queues = {}
    fwd_ports = []
    for port in port_docs:
        if not isinstance(port, dict) or frozenset(port) != expected:
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        rates = _validate_link_state_rates(port["rates"])
        modes = _validate_link_state_modes(port["modes"])
        caps[name] = (rates, modes)
        queue_bytes = port["queue_bytes"]
        if not _is_int(queue_bytes) or queue_bytes < 0:
            raise InvalidInput("bad queue_bytes")
        queues[name] = queue_bytes
        fwd_ports.append(
            {
                "name": name,
                "mode": port["mode"],
                "pvid": port["pvid"],
                "allowed": port["allowed"],
                "untagged": port["untagged"],
                "up": False,
            }
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    validate_forward_config_v2({"ports": fwd_ports, "age": age})
    return fwd_ports, caps, queues, age, max_frame, delay


def validate_link_wire_events(events, fwd_ports):
    """link/frame 形状同 link-forward，另接受 {"t", advance:true}；t 单调不减。"""
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in fwd_ports}
    result = []
    prev_t = None
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == LINK_WIRE_ADVANCE_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if event["advance"] is not True:
                raise InvalidInput("bad advance")
            result.append(("advance", t))
        elif keys == LINK_WIRE_LINK_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            port = event["port"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            admin = event["admin"]
            peer = event["peer"]
            if not isinstance(admin, bool) or not isinstance(peer, bool):
                raise InvalidInput("bad admin/peer")
            rates = _validate_link_state_rates(event["rates"])
            modes = _validate_link_state_modes(event["modes"])
            result.append(("link", t, port, admin, peer, rates, modes))
        elif keys == LINK_WIRE_FRAME_EVENT_KEYS:
            t = event["t"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            port = event["port"]
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            src = event["src"]
            dst = event["dst"]
            tag = event["vlan"]
            length = event["length"]
            fcs = event["fcs"]
            alignment = event["alignment"]
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if dst != BROADCAST_MAC and not valid_mac(dst):
                raise InvalidInput("bad dst")
            if tag is not None and not _valid_vlan_id(tag):
                raise InvalidInput("bad vlan")
            if not _is_int(length) or length < 0:
                raise InvalidInput("bad length")
            if not isinstance(fcs, bool):
                raise InvalidInput("bad fcs")
            if not isinstance(alignment, bool):
                raise InvalidInput("bad alignment")
            result.append(
                ("frame", t, port, src, dst, tag, length, fcs, alignment)
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result


def _link_wire_indexed(fwd_ports, events):
    """link-wire 实际处理顺序：(t, 端口配置序, 原序) 稳定排列，advance 无
    端口，置于同一时刻最后。返回 (原下标, 事件) 列表。"""
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    indexed = list(enumerate(events))
    indexed.sort(
        key=lambda ix: (
            ix[1][1],
            len(fwd_ports) if ix[1][0] == "advance" else order[ix[1][2]],
            ix[0],
        )
    )
    return indexed


def link_wire(
    fwd_ports, caps, queues, age, max_frame, delay, events, work_limit=None,
    observer=None,
):
    """link-wire 仿真。

    work_limit 非 None 时在各计费点累计工作量 W（初值 P），首次超过即抛
    LinkWireWorkLimit；预演与正式仿真共用本函数（独立状态、无部分输出）。
    observer 非 None 时（record/replay）按实际处理顺序逐事件记录
    {"kind", "t", "applied", "output"}：output 为该事件开始时到期结算
    结果后接该事件自身结果在直接结果数组中的连续片段；frame 恒 applied；
    link 仅目标链路状态实际改变时 applied；advance 仅实际完成至少一个
    到期协商或发送时 applied。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    committed = {name: ("down",) for name in by_name}
    pending = {}  # name -> (rate, mode, deadline)
    fdb = {}  # (vlan, mac) -> [port, seen]
    # 每口未完成副本：deque，按入队（即串行发送）顺序，队头为正在发送副本
    outstanding = {name: deque() for name in by_name}
    occupied = {name: 0 for name in by_name}  # 未完成副本线上字节总和
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
        }
        for name in by_name
    }
    results = []
    if observer is not None:  # record/replay：按处理顺序逐事件记录
        observer["items"] = []
    work = len(fwd_ports)  # W 初值 P
    if work_limit is not None and work > work_limit:
        raise LinkWireWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise LinkWireWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

    def settle_negotiations(t):
        # 完成截止 <= t 的协商，口序同配置（与 link-state/link-forward 一致）；
        # 返回完成的协商数（协商到期本身不产生 results 记录）
        settled = 0
        for port in fwd_ports:
            name = port["name"]
            if name in pending and pending[name][2] <= t:
                rate, mode, _ = pending.pop(name)
                committed[name] = ("up", rate, mode)
                settled += 1
        return settled

    def settle_transmissions(t):
        # 结算结束时刻 <= t 的发送：全局按 (end, 口配置序) 逐项弹出队头；
        # 同口串行且时长为正，弹出一口队头后其下一副本 end 必更晚。
        while True:
            best = None  # (end, port_index, name)
            for name in by_name:
                q = outstanding[name]
                if q and q[0]["end"] <= t:
                    cand = (q[0]["end"], order[name], name)
                    if best is None or cand < best:
                        best = cand
            if best is None:
                return
            name = best[2]
            copy = outstanding[name].popleft()
            occupied[name] -= copy["bytes"]
            stats[name]["tx_frames"] += 1
            stats[name]["tx_bytes"] += copy["bytes"]
            results.append(
                {"t": copy["end"], "port": name,
                 "start": copy["start"], "bytes": copy["bytes"]}
            )
            charge()

    def settle(t):
        # 返回本次完成的到期协商数（发送完成不返回值，以 results 增量计）
        negotiated = settle_negotiations(t)
        settle_transmissions(t)
        return negotiated

    def apply_link(t, port, admin, peer, rates, modes):
        """同 link-forward 的协商状态迁移；返回 (state,rate,mode,applied)。"""
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        before_up = port not in pending and committed[port][0] == "up"
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False  # 目标未变：不改变协商状态
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            pending.pop(port, None)
            committed[port] = target
            applied = True
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
            now_up = False
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
                now_up = True
            else:
                state, rate, mode = now[0], None, None
                now_up = False

            raise ForwardWorkLimit
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        # 坏帧（含 forward-decode 恒真的 alignment）不计 VLAN、不学习
        if (
            length < FRAME_CHECK_RUNT_LENGTH
            or length > max_frame
            or not alignment
            or not fcs
        ):
            continue
        ingress = by_name[port_name]
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
        else:
            vlan = tag
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if not rejected and ingress["up"]:
            fdb[(vlan, src)] = [port_name, t]


def validate_forward_decode_frames(frames, ports):
    # 帧外壳契约（t/port/data、单层 8100、双标签拒绝）与 frame-decode
    # 一致，复用其全量校验；ports 为新式端口字典，取其名字集合
    checked = validate_frame_decode_frames(
        frames, [port["name"] for port in ports]
    )
    for _, _, raw in checked:
        dst = raw[0:6]
        src = raw[6:12]
        if not any(dst):  # 目的 MAC 全零非法
            raise InvalidInput("bad dst")
        if not any(src) or src[0] & 1:  # 源 MAC 须为非零单播
            raise InvalidInput("bad src")
    return checked


def _decode_raw_frames(frames):
    """按 frame-decode 规则解析原始帧为 forward_check 的八元组帧序。

    无对齐概念，alignment 恒真，分类退化为 runt/giant/bad_fcs/good。
    """
    checked = []
    for t, port, raw in frames:
        dst = _format_mac(raw[0:6])
        src = _format_mac(raw[6:12])
        if raw[12:14] == FRAME_DECODE_TAG:
            tci = (raw[14] << 8) | raw[15]
            vlan = tci & 0x0FFF
        else:
            vlan = None
        fcs = raw[-4:] == (zlib.crc32(raw[:-4]) & 0xFFFFFFFF).to_bytes(
            4, "little"
        )
        checked.append((t, port, src, dst, vlan, len(raw), fcs, True))
    return checked


def forward_decode(frames, ports, age, max_frame):
    # 按 frame-decode 规则解析原始帧，再接入新式 forward（forward_check）
    return forward_check(_decode_raw_frames(frames), ports, age, max_frame)


