    数组含 src（八键）按 forward-check，含 data（t/port/data 原始帧）按
    forward-decode；两种帧形状混用报 InvalidInput；空数组沿用既有
    forward-decode 路由（既有日志字节不变）。stp 七键配置的非链路帧含
    src（九键）按 stp-check，含 data（t/port/data 原始帧）按 stp-decode；
    两种帧形状混用报 InvalidInput；仅链路项或空事件沿用既有 stp-decode
    路由（既有日志字节不变）。qos 十二键配置的帧项含 src（十键）按
    qos-check，含 data（t/port/data 原始帧）按 qos-decode，两种帧形状
    混用报 InvalidInput；仅链路/成员/service 项或空事件沿用既有
    qos-check 路由（既有日志字节不变）。
    """
    if isinstance(config, dict):
        keys = frozenset(config)
        # 恰含 ports,age 且 ports 为字符串数组时为 fdb 模式（forward 旧
        # 入口的 ports 为对象数组，形状不重叠）
        if keys == CONFIG_KEYS and isinstance(
            config.get("ports"), list
        ) and all(isinstance(p, str) for p in config["ports"]):
            return "fdb"
        # 恰含 ports,age 且 ports 为非空对象数组时为 forward 模式，旧式
        # access（name/vlan/up）与新式 802.1Q（name/mode/pvid/allowed/
        # untagged/up）两种端口形状均沿用 forward 入口识别与校验
        if (
            keys == CONFIG_KEYS
            and isinstance(config.get("ports"), list)
            and bool(config["ports"])
            and all(isinstance(p, dict) for p in config["ports"])
        ):
            return "forward"
        if keys == STP_CONFIG_KEYS:
            return "stp"
        if keys == LOOP_CONFIG_KEYS:
            return "loop"
        if keys == LINK_FORWARD_CONFIG_KEYS:
            # link-wire 与 link-forward 顶层同键，但端口形状不重叠：
            # link-wire 每口恰多 queue_bytes（八键）。端口文档均含
            # queue_bytes 即按 link-wire 路由（事件可含 advance），其余
            # 沿用 link-forward；形状不全者由对应全量校验判非法。
            ports_doc = config.get("ports")
            if (
                isinstance(ports_doc, list)
                and ports_doc
                and all(
                    isinstance(p, dict) and "queue_bytes" in p
                    for p in ports_doc
                )
            ):
                return "link_wire"
            return "link_forward"
        if keys == LINK_STATE_CONFIG_KEYS:
            return "link_state"
        if keys == FORWARD_STATIC_CONFIG_KEYS:
            return "forward_static"
        if keys == FORWARD_STP_CONFIG_KEYS:
            return "forward_stp"
        if keys == FORWARD_CHECK_CONFIG_KEYS:
            # forward-check 与 forward-decode 共享三键配置：非空帧数组含
            # src（八键）按 forward-check，含 data 按 forward-decode，两种
            # 帧形状混用即非法输入；空数组沿用既有 forward-decode 路由
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == FORWARD_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                else:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "forward_check" if saw_src else "forward_decode"
        if keys == STP_CHECK_CONFIG_KEYS:
            # stp-check 与 stp-decode 共享七键配置：非链路帧含 src 按
            # stp-check，含 data 按 stp-decode，两种帧形状混用即非法输入
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == STP_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys != STP_EVENT_KEYS:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "stp_check" if saw_src else "stp_decode"
        if keys == STORM_CONFIG_KEYS:
            return "forward_stp_storm"
        if keys == LAG_CONFIG_KEYS:
            return "lag"
        if keys == MIRROR_CONFIG_KEYS:
            return "mirror"
        if keys == ACL_CONFIG_KEYS:
            return "acl"
        if keys == ACL_CHECK_CONFIG_KEYS:
            return "acl_check"
        if keys == QOS_CONFIG_KEYS:
            return "qos"
        if keys == QOS_CHECK_CONFIG_KEYS:
            # qos-check 与 qos-decode 共享十二键配置：非链路/成员/service
            # 帧含 src（十键）按 qos-check，含 data（t/port/data 原始帧）
            # 按 qos-decode，两种帧形状混用即非法输入；无非帧帧项时沿用
            # 既有 qos-check 路由（既有日志字节不变）
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == QOS_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys not in (
                    STP_EVENT_KEYS, MEMBER_EVENT_KEYS, SERVICE_EVENT_KEYS
                ):
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "qos_decode" if saw_data else "qos_check"
        if keys == SECURITY_CHECK_CONFIG_KEYS:
            return "security_check"
        if keys == MIRROR_CHECK_CONFIG_KEYS:
            return "mirror_check"
        if keys == LAG_CHECK_CONFIG_KEYS:
            return "lag_check"
        if keys == STORM_CHECK_CONFIG_KEYS:
            return "storm_check"
    return "security"


def _run_fdb(config, events, observe, max_work=None):
    """record/replay fdb 模式：校验 fdb 配置与事件并执行仿真。

    语义同 fdb 子命令；max_work 非 None 时（record/replay）全量语义校验后
    先按 fdb 公式（逐事件累计 K+1，K 为老化前表项数）以独立空映射无副作用
    预演，首次超过即抛 FdbWorkLimit，不正式仿真。返回 (fdb 结果 dict,
    observer 或 None)；每项 output 恒 None，applied 与 version 由
    _build_log_doc/_verify_records 按 FDB 是否实际改变计算。
    """
    ports, age = validate_config(config)
    fdb_events = validate_events(events, ports)
    if max_work is not None:
        # 与 fdb 入口同一公式：独立空 FDB，无副作用
        fdb_work(fdb_events, age, max_work)
    observer = {} if observe else None
    result = simulate(fdb_events, age, observer=observer)
    return result, observer


def _run_stp(config, events, observe, max_work=None):
    """record/replay STP 模式：校验 stp 配置与事件并执行仿真。

    语义同 stp 子命令；max_work 非 None 时（record）全量语义校验后先按
    stp 公式无副作用预演（在 _stp_run 内、正式输出前完成），首次超过即
    抛 StpWorkLimit，不正式仿真。返回 (stp 结果 dict, observer 或 None)。
    """
    bridges, links, delay = validate_stp_config(config)
    link_ids = {link["id"] for link in links}
    stp_events = validate_stp_events(events, link_ids)
    observer = {} if observe else None
    result = _stp_run(
        bridges, links, delay, stp_events, max_work, observer=observer
    )

    # applied 但不计），forward-static 模式帧恒 applied 且 version 恒 0
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if mode in ("fdb", "stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode in (
            "link_forward", "link_wire", "forward_stp", "stp_decode",
            "stp_check", "forward_stp_storm"
        ):
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode in (
            "qos", "lag", "mirror", "acl", "security_check", "qos_check",
            "qos_decode",
            "acl_check", "mirror_check", "lag_check", "storm_check"
        ):
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
